class Saudacoes
{
    public function __construct() {}

    public static function ola()
    {

        date_default_timezone_set('America/Sao_Paulo');
        $nome = Confide::user() ? Confide::user()->username : '';
        $hr = date(' H ');

        if ($hr >= 12 && $hr < 20) {
            $turno = 'Boa tarde';
        } elseif ($hr >= 20 && $hr < 24) {
            $turno = 'Boa noite';
        } elseif ($hr >= 0 && $hr < 6) {
            $turno = "Dormir é para os fracos \o/";
        } elseif ($hr >= 6 && $hr < 12) {
            $turno = 'Bom dia';
        } else {
            $turno = 'Que horas são?';
        }

        return $turno;
    }
}

